def icon_svg(name: str, size: int | str = 20, stroke: float = 1.8, class_name: str = "icon") -> str:
    paths = LUCIDE_ICONS.get(name, LUCIDE_ICONS["circle-dot"])
    return (
        f"<svg class='{esc(class_name)}' width='{esc(size)}' height='{esc(size)}' viewBox='0 0 24 24' "
        f"fill='none' stroke='currentColor' stroke-width='{stroke:.2f}' stroke-linecap='round' "
        f"stroke-linejoin='round' aria-hidden='true'>{''.join(paths)}</svg>"
    )


